import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useAuth } from '@workspace/replit-auth-web';
import { UserSwitcher, STAFF_PROFILES } from '@/components/UserSwitcher';
import { JobTicketModal } from '@/components/JobTicketModal';
import { PrintCalculatorModal } from '@/components/PrintCalculatorModal';
import { MessageCircle, Calculator } from 'lucide-react';
import {
  useGetDashboard, useListActivity, useListClients, useCreateClient, useListTickets, useCreateTicket,
  useGetTicket, useAnalyzeTicket, useCreateArtworkVersion, useDecideTicketProduction,
  useGetSampleApproval, useDecideSampleApproval, useListOrders, useGetOrder, useUpdateOrderStage,
  useSubmitQualityCheck, useUpdateOrderDelivery, useListTeamMembers, useUpdateTeamRole, useRequestUploadUrl,
  getGetDashboardQueryKey, getListActivityQueryKey, getListClientsQueryKey, getListTicketsQueryKey,
  getGetTicketQueryKey, getGetSampleApprovalQueryKey, getListOrdersQueryKey, getGetOrderQueryKey,
  getListTeamMembersQueryKey,
} from '@workspace/api-client-react';
